$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));. (Join-Path $PSScriptRoot 'Blueprint.Catalog.ps1');$catalog=Test-SpectraBlueprintCatalog $root;if(@($catalog.blueprints).Count-ne4){throw 'BLUEPRINT_PACKAGE_COUNT_INVALID'};$required=@('BPC-CONFLUENCE-PROJECT','BPC-JIRA-PROJECT','BPC-BLANK-DOCUMENTS','BPC-METADATA');foreach($id in $required){if(@($catalog.blueprints|Where-Object id -eq $id).Count-ne1){throw 'BLUEPRINT_REQUIRED_PACKAGE_MISSING'}};Write-Host "PASS: $(@($catalog.blueprints).Count) Blueprint-Pakete und $(@($catalog.blueprints.artifacts).Count) Vorlagen sind versioniert, leer und sicher."
